<template><section class="panel"><header class="panel__header"><h2>Relatório de ocorrências</h2></header><div class="filters"><label>Cobrador<select v-model="collector" class="field"><option value="">Todos</option><option v-for="user in users" :key="user.id" :value="String(user.id)">{{ user.nome }}{{ user.ativo ? '' : ' (desativado)' }}</option></select></label><label>Data inicial<input v-model="start" class="field" type="date"></label><label>Data final<input v-model="end" class="field" type="date"></label><button class="primary-button" type="button" @click="print">Gerar relatório</button></div><p class="hint">Mostra Fechado e Não pagou. O link “Abrir mapa” no PDF abre a localização no Google Maps.</p><p v-if="error" class="feedback feedback--error">{{ error }}</p></section></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {apiFetch,apiFetchBlob} from '@/services/http';const today=new Date().toISOString().slice(0,10),start=ref(today),end=ref(today),collector=ref(''),users=ref<Array<{id:number;nome:string;ativo:boolean}>>([]),error=ref('');onMounted(async()=>{try{users.value=await apiFetch<Array<{id:number;nome:string;ativo:boolean}>>('/financeiro/relatorios/recebimentos/cobradores')}catch{error.value='Não foi possível carregar os usuários.'}});async function print(){const query=new URLSearchParams({data_inicial:start.value,data_final:end.value});if(collector.value)query.set('cobrador_id',collector.value);try{const blob=await apiFetchBlob(`/financeiro/relatorios/ocorrencias/imprimir?${query}`),url=URL.createObjectURL(blob);window.open(url,'_blank','noopener,noreferrer');window.setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(cause){error.value=cause instanceof Error?cause.message:'Não foi possível gerar o relatório.'}}</script><style scoped>.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:end}.filters label{display:grid;gap:4px;font-size:13px}.hint{color:var(--text-muted);font-size:13px}</style>
